export function obterNomeFazenda(fazendaId: string): string {
  const f = FAZENDAS_DISPONIVEIS.find(item => item.id === fazendaId);
  if (f) {
    return `${f.id} - ${f.nome} (${f.municipio} - ${f.uf})`;
  }
  return `Fazenda ${fazendaId}`;
}

export function obterDescricaoFazenda(fazendaId: string): string {
  const f = FAZENDAS_DISPONIVEIS.find(item => item.id === fazendaId);
  return f ? f.nome : `FAZ. ${fazendaId}`;
}

export function obterApontadorPorFazenda(fazendaId: string, apontadores: ApontadorInfo[] = APONTADORES_DISPONIVEIS): ApontadorInfo | undefined {
  return apontadores.find(item => item.fazendasIds.includes(fazendaId));
}

